import {Hollow} from './sim.js';
import {WORLD,YARD,STATIONS,WEAPONS,ARMORS,MATERIALS,RECIPES,DESTINATIONS,PALETTES,SKINS,HAIR_COLORS,TROUSER_COLORS,LOOK_OPTIONS} from './data.js';
