const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}};
let stored=read(SAVE,null),model;try{model=stored?Hollow.restore(stored):new Hollow();}catch{model=new Hollow();stored=null;}
let settings={sound:false,low:false,size:'medium',reach:'edge',opacity:32,assist:true,...read(SETTINGS,{})};
if(!['small','medium','large'].includes(settings.size))settings.size='medium';if(!['edge','inward'].includes(settings.reach))settings.reach='edge';settings.opacity=Math.min(70,Math.max(15,Number(settings.opacity)||32));
let game,scene,ready=false,welcome=true,panel=null,lastFocus=null,panelData=null,selectedRecipe='tonic',craftCategory='Supplies',gearTab='Weapons',layout,saveAge=0,lastHud=0,toastTimer,hintTimer=12,move={x:0,y:0,power:0},aim={x:0,y:0,power:0},mouse={x:0,y:0,seen:false,down:false},lastInput={mx:0,my:0};const keys=new Set();
const touch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0;if(touch)document.body.classList.add('touch');
