let audio;
function sound(type){if(!settings.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{});if(audio.state!=='running')return;let o=audio.createOscillator(),g=audio.createGain(),f={shot:180,heal:510,craft:650,loot:720,dash:130,hurt:70,drillStart:260,kill:90}[type]||400;o.type=type==='shot'?'triangle':'sine';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f*(type==='shot'?.3:1.6)),audio.currentTime+.12);g.gain.setValueAtTime(type==='shot'?.022:.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.15);}catch{}}
function toast(s){$('toast').textContent=s;show('toast');clearTimeout(toastTimer);toastTimer=setTimeout(()=>hide('toast'),3200);}
let saveWarned=false;function save(){try{localStorage.setItem(SAVE,JSON.stringify(model.snapshot()));}catch{if(!saveWarned){toast('Saving is unavailable in this browser session.');saveWarned=true;}}}
function saveSettings(){try{localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}resize();}
function place(id,b){Object.assign($(id).style,{left:b.x+'px',top:b.y+'px',width:b.w+'px',height:b.h+'px'});}
function resize(){let vv=window.visualViewport,w=Math.round(vv?.width||innerWidth),h=Math.round(vv?.height||innerHeight),st=document.documentElement.style;st.setProperty('--view-w',w+'px');st.setProperty('--view-h',h+'px');st.setProperty('--view-x',(vv?.offsetLeft||0)+'px');st.setProperty('--view-y',(vv?.offsetTop||0)+'px');st.setProperty('--stick-opacity',settings.opacity/100);game?.scale.resize(w,h);let c=getComputedStyle($('safeAreaProbe')),safe={left:parseFloat(c.paddingLeft)||0,right:parseFloat(c.paddingRight)||0,top:parseFloat(c.paddingTop)||0,bottom:parseFloat(c.paddingBottom)||0};layout=touchLayout(w,h,safe,settings.size,settings.reach);if(touch){for(let [id,b]of [['moveStick',layout.move],['aimStick',layout.aim]]){place(id,b);$(id).style.setProperty('--home-x',b.cx+'px');$(id).style.setProperty('--home-y',b.cy+'px');$(id).style.setProperty('--diameter',layout.ring*2+'px');}place('dash',layout.dash);place('heal',layout.heal);place('weaponDock',layout.dock);$('interact').style.bottom=(h-layout.dock.y+12)+'px';}resetInput();}
function resetInput(){keys.clear();mouse.down=false;move={x:0,y:0,power:0};aim={x:0,y:0,power:0};for(let id of ['moveStick','aimStick'])$(id).resetStick?.();}
window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);document.addEventListener('fullscreenchange',resize);
function stick(id,assign){let el=$(id),s=new FloatingStick(),box,ring=el.querySelector('.ring'),thumb=el.querySelector('.thumb');function clear(pointer=s.pointer){if(!s.end(pointer))return;assign({x:0,y:0,power:0});el.classList.remove('active');ring.style.left=ring.style.top=thumb.style.left=thumb.style.top='';thumb.style.transform='';}function paint(v){ring.style.left=v.baseX+'px';ring.style.top=v.baseY+'px';thumb.style.left=v.baseX+'px';thumb.style.top=v.baseY+'px';thumb.style.transform=`translate(-50%,-50%) translate(${v.thumbX}px,${v.thumbY}px)`;}
 el.addEventListener('pointerdown',e=>{if(bridge.paused()||s.pointer!==null)return;e.preventDefault();box=el.getBoundingClientRect();s.start(e.pointerId,e.clientX-box.left,e.clientY-box.top,{w:box.width,h:box.height},layout.ring,layout.travel);el.setPointerCapture(e.pointerId);assign({x:0,y:0,power:0});el.classList.add('active');paint({baseX:s.base.x,baseY:s.base.y,thumbX:0,thumbY:0});});el.addEventListener('pointermove',e=>{let v=s.move(e.pointerId,e.clientX-box?.left,e.clientY-box?.top);if(!v)return;e.preventDefault();assign(stickVector(v.dx,v.dy,s.travel,.1));paint(v);});for(let event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,e=>clear(e.pointerId));el.resetStick=()=>clear();}
