function act(a){if(bridge.paused())return;if(a==='dash')model.dash(lastInput.mx,lastInput.my);if(a==='heal'){if(!model.heal())toast(model.tonics?'Health is already full.':'Craft more tonics at the workshop.');}if(a==='reload')model.reload();}
