const row=(title,sub,action,id='',active=false,badge='')=>`<button class="row-button ${active?'active':''}" data-action="${action}" data-id="${id}"><span><b>${title}</b><small>${sub}</small></span><span class="badge">${badge||'↗'}</span></button>`;
