function renderPanel(){if(panel==='map'){shell('Your corner of the world','DEADLIGHT HOLLOW',`<div class="two-columns"><div class="column"><div class="map-wrap"><canvas id="mapCanvas" width="700" height="390"></canvas></div><p class="map-note">Visit on foot, or use a village shortcut. The yard is beyond the beach path to the southeast.</p></div><div class="column list">${DESTINATIONS.map((d,i)=>row(d.name,'Village shortcut','travel',i,false,'GO →')).join('')}</div></div>`,model.drill?'<p>Shortcuts are unavailable during a drill.</p>':'<p>The village is safe. Take your time.</p>');drawOverview($('mapCanvas').getContext('2d'),700,390,model);}
 if(panel==='equipment'){let list=gearTab==='Weapons'?Object.entries(WEAPONS).map(([id,w])=>row(w.name,`${Math.round(w.damage*(1+model.upgrades[id]*.15))}${w.pellets>1?' × '+w.pellets:''} damage · ${w.clip} rounds · Tuning ${model.upgrades[id]}/3`,'equip',id,model.weapon===id,model.weapon===id?'EQUIPPED':'EQUIP')).join(''):Object.entries(ARMORS).map(([id,a])=>row(a.name,a.desc,'equip',id,model.armor===id,model.armor===id?'EQUIPPED':model.owned.includes(id)?'EQUIP':'CRAFT FIRST')).join('');shell('Equipment & supplies','PREPARE YOUR OWN WAY',`<div class="two-columns"><div class="column"><div class="tabs">${['Weapons','Armor'].map(t=>`<button data-action="gearTab" data-id="${t}" class="${gearTab===t?'active':''}">${t}</button>`).join('')}</div><div class="list">${list}</div></div><div class="column"><p class="section-label">YOUR SUPPLIES</p>${resources()}<p class="notice">All four training weapons are available. Build armor and improve weapons at the Salvage Works. Ammunition reserves are unlimited in this training build.</p></div></div>`,model.drill?'<p>Equipment is locked for the current drill.</p>':'<p>Your equipment defines your role. No class selection required.</p>');}
 if(panel==='craft'){let recipe=RECIPES.find(r=>r.id===selectedRecipe)||RECIPES[0],tier=recipe.weapon?model.upgrades[recipe.weapon]+1:1,done=model.owned.includes(recipe.id)||(recipe.weapon&&tier>3)||(recipe.id==='tonic'&&model.tonics>=6),enough=Object.entries(recipe.cost).every(([k,n])=>model.materials[k]>=n*tier);shell('The Salvage Works','MARA · QUARTERMASTER',`<div class="two-columns"><div class="column"><div class="tabs">${['Supplies','Weapons','Armor'].map(c=>`<button data-action="craftTab" data-id="${c}" class="${craftCategory===c?'active':''}">${c}</button>`).join('')}</div><div class="list">${RECIPES.filter(r=>r.category===craftCategory).map(r=>row(r.name,r.weapon?'Tier '+Math.min(3,model.upgrades[r.weapon]+1)+' / 3':r.category,'recipe',r.id,r.id===recipe.id,'→')).join('')}</div></div><div class="detail"><h3>${recipe.name}</h3><p>${recipe.desc}</p><div class="costs">${Object.entries(recipe.cost).map(([k,n])=>`<div class="${model.materials[k]<n*tier?'missing':''}"><span>${MATERIALS[k]}</span><b>${model.materials[k]} / ${n*Math.min(3,tier)}</b></div>`).join('')}</div><p>Owned / required. Materials are saved with your character.</p></div></div>`,`<p>${done?'Already fully stocked or upgraded.':enough?'Everything you need is here.':'Search the village caches or complete a training drill for materials.'}</p><button class="primary" data-action="craft" data-id="${recipe.id}" ${done||!enough?'disabled':''}>${recipe.weapon?'Improve weapon':'Craft item'} →</button>`);}
 if(panel==='appearance'){
 const swatches=(title,key,colors)=>`<p class="section-label">${title}</p><div class="swatches">${colors.map((col,i)=>`<button aria-label="${title} ${i+1}" aria-pressed="${model.look[key]===i}" class="swatch ${model.look[key]===i?'active':''}" style="--color:${col}" data-action="look" data-key="${key}" data-id="${i}"></button>`).join('')}</div>`;
 const choices=(title,key)=>`<p class="section-label">${title}</p><div class="choice-row">${LOOK_OPTIONS[key].map((name,i)=>`<button data-action="look" data-key="${key}" data-id="${i}" aria-pressed="${model.look[key]===i}" class="${model.look[key]===i?'active':''}">${name}</button>`).join('')}</div>`;
 const sections={Body:()=>choices('BODY','body')+swatches('SKIN TONE','skin',SKINS)+'<p class="copy">Every hairstyle, outfit, and facial hair option is available to both bodies.</p>',Face:()=>choices('NOSE','nose')+choices('FACIAL HAIR','beard'),Hair:()=>choices('HAIRSTYLE','hair')+swatches('HAIR & FACIAL HAIR COLOR','hairColor',HAIR_COLORS)+choices('HEADWEAR','headwear'),Clothing:()=>choices('CLOTHING CUT','outfit')+swatches('CLOTHING COLOR','coat',PALETTES)+swatches('TROUSER COLOR','trousers',TROUSER_COLORS)+choices('PACK','pack')};
 shell('Make yourself at home','NELL · THREAD & TIDE',`<div class="two-columns appearance-layout"><div class="look-preview"><canvas id="portrait" width="720" height="440" role="img" aria-label="${['Front','Back','Left','Right'][previewDirection]} character preview, close-up and full figure"></canvas><p>CLOSE-UP · FULL FIGURE</p><div class="preview-directions" aria-label="Preview direction">${['Front','Back','Left','Right'].map((name,i)=>`<button data-action="lookDirection" data-id="${i}" aria-pressed="${previewDirection===i}" class="${previewDirection===i?'active':''}">${name}</button>`).join('')}</div><button class="preview-gear" data-action="lookGear" aria-pressed="${previewGear}">${previewGear?'Equipment shown':'Show equipped gear'}</button></div><div class="creator-controls"><nav class="tabs creator-tabs" aria-label="Appearance categories">${Object.keys(sections).map(name=>`<button data-action="lookTab" data-id="${name}" aria-pressed="${appearanceTab===name}" class="${appearanceTab===name?'active':''}">${name}</button>`).join('')}</nav><div class="column creator-options">${sections[appearanceTab]()}</div></div></div>`,'<p>Your look saves automatically. Clothing and body choices are cosmetic.</p><button data-action="close" class="primary">Looks like me ✓</button>');
 let c=$('portrait').getContext('2d');c.clearRect(0,0,720,440);c.imageSmoothingEnabled=false;c.scale(2,2);
 const angle=[Math.PI/2,-Math.PI/2,Math.PI,0][previewDirection],look={...model.look,armor:previewGear?model.armor:'scout',weapon:previewGear?model.weapon:null,armed:previewGear};
 for(let [x,y,scale]of [[35,0,2],[240,96,1]]){c.save();c.translate(x,y);c.scale(scale,scale);person(c,look,angle,0);c.restore();}
 }
 if(panel==='training'){let acc=model.stats.shots?Math.round(model.stats.hits/model.stats.shots*100):0;shell('Room to find your footing','ROOK · TRAINING YARD',`<div class="two-columns"><div class="column"><p class="copy">Shoot the targets freely, or start a controlled encounter. Dummies reset after each takedown. Live-drill defeat has no permanent cost.</p><div class="list">${row('Target practice','Reset the targets and damage readout.','targets')}${row('First steps','8 slow-pressure opponents · reduced damage','drill','gentle')}${row('Hold your ground','16 mixed opponents · standard pressure','drill','standard')}${row('Crowd control','28 opponents · faster arrivals','drill','swarm')}</div></div><div class="column"><p class="section-label">CURRENT PRACTICE</p><div class="stats"><div><b>${model.stats.damage}</b><small>DAMAGE</small></div><div><b>${acc}%</b><small>ACCURACY</small></div><div><b>${model.stats.shots}</b><small>SHOTS FIRED</small></div><div><b>${model.records.drills}</b><small>DRILLS COMPLETED</small></div></div><p class="notice">Drills supply three practice tonics and restore your original stock afterward. Completed drills award 6 scrap, 2 herbs, and 1 precision part. Leaving the app ends the saved drill safely.</p></div></div>`,'<p>Movement, aim, dash, healing, reloads, and armor all work here.</p><button data-action="equipment" class="primary">Choose equipment ↗</button>');}
 if(panel==='report'){let r=panelData;shell(r.result==='complete'?'Steady hands.':'Another chance to learn.','TRAINING REPORT',`<div class="two-columns"><div class="column"><p class="quote">${r.result==='complete'?'“Good work. Take that confidence with you.”':r.result==='downed'?'“You are all right. Reset your stance. We go again when you are ready.”':'“There is no rush here. Come back when you are ready.”'}</p><p class="copy">${r.result==='complete'?'Added to your supplies: 6 scrap, 2 coastal herbs, 1 precision part.':'Health restored. Your original tonic stock is safe.'}</p></div><div class="stats"><div><b>${r.kills}</b><small>OPPONENTS CLEARED</small></div><div><b>${Math.round(r.time)}s</b><small>TIME</small></div><div><b>${r.shots?Math.round(r.hits/r.shots*100):0}%</b><small>ACCURACY</small></div><div><b>${r.damage}</b><small>DAMAGE</small></div></div></div>`,'<button data-action="close">Back to the yard</button><button data-action="training" class="primary">Train again ↗</button>');}
 if(panel==='talk'||panel==='clinic'||panel==='supplies'){let s=panelData;shell(s.label,s.person.toUpperCase()+' · '+s.role.toUpperCase(),`<p class="quote">“${s.text}”</p>${panel==='supplies'?resources():`<p class="notice">${panel==='clinic'?'Rest here to restore your health. Treatment is free in the village.':'The village and training yard are open to explore. Expeditions will come later.'}</p>`}`,`<p>${panel==='supplies'&&model.allowance?'Your welcome supplies have already been collected.':''}</p>${panel==='clinic'?'<button data-action="rest" class="primary">Rest & recover</button>':panel==='supplies'?`<button data-action="allowance" class="primary" ${model.allowance?'disabled':''}>Collect welcome supplies</button>`:'<button data-action="close" class="primary">See you around</button>'}`);}
 if(panel==='pause'){shell('The world can wait','PAUSED & SAVED',`<div class="two-columns"><div class="column list">${row('Back to the hollow','Continue exploring','close')}${row('Village map','Find the workshop, clinic, beach, or yard','map')}${row('Your appearance','Colors, hair, and headwear','appearance')}${row('Save & return to title','Keep your village progress','title')}<a class="link" href="classic.html">Original wave-survival prototype ↗</a></div><div class="column"><label class="setting">Sound<button data-action="sound">${settings.sound?'On ♪':'Off'}</button></label><label class="setting">Rendering<select id="quality"><option value="full" ${!settings.low?'selected':''}>Full</option><option value="low" ${settings.low?'selected':''}>Battery saver</option></select></label><label class="setting">Control size<select id="size">${['small','medium','large'].map(v=>`<option ${settings.size===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="setting">Thumb position<select id="reach"><option value="edge" ${settings.reach==='edge'?'selected':''}>Outer edges</option><option value="inward" ${settings.reach==='inward'?'selected':''}>Closer in</option></select></label><label class="setting">Stick visibility<input id="opacity" type="range" min="15" max="70" value="${settings.opacity}"></label><button data-action="fullscreen" class="text-button">Full-screen / iPhone setup ↗</button><p class="fine">WASD + mouse · E interact · Space dash · Q tonic · R reload · M map · Tab equipment · Esc pause</p></div></div>`,'<p>Progress is saved on this device. Co-op is planned; this build is solo.</p>');$('quality').onchange=e=>{settings.low=e.target.value==='low';saveSettings();};$('size').onchange=e=>{settings.size=e.target.value;saveSettings();};$('reach').onchange=e=>{settings.reach=e.target.value;saveSettings();};$('opacity').oninput=e=>{settings.opacity=Number(e.target.value);saveSettings();};}
 if(panel==='install')shell('Give the hollow the screen','IPHONE / LANDSCAPE',`<div class="two-columns"><div class="column"><p class="quote">A little more room to breathe.</p><p class="copy">Launch from your iPhone Home Screen for an app-style view without Safari’s address and tab bars.</p></div><div class="column"><ol class="install-steps"><li>Open this game in <b>Safari</b>.</li><li>Tap <b>Share → Add to Home Screen</b>. Keep <b>Open as Web App</b> on if shown.</li><li>Launch the new icon and turn your phone sideways.</li></ol><p class="fine">Use the same app/browser for your saves. Home Screen storage may be separate.</p></div></div>`,'<p>Turn off Portrait Orientation Lock if the screen will not rotate.</p><button class="primary" data-action="close">Ready ✓</button>');
}
async function panelAction(e){let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let a=b.dataset.action,id=b.dataset.id;if(a==='close')return close();if(['map','equipment','appearance','training'].includes(a))return open(a);if(a==='travel'){if(model.travel(Number(id))){scene?.cameras.main.centerOn(model.p.x,model.p.y*WORLD.sy);close();save();}else toast('Finish or end the drill before using a shortcut.');return;}if(a==='gearTab'){gearTab=id;return renderPanel();}if(a==='equip'){if(model.equip(id)){sound('craft');save();renderPanel();}else toast(model.drill?'Finish the current drill first.':'Craft this armor at the workshop.');return;}if(a==='craftTab'){craftCategory=id;selectedRecipe=RECIPES.find(r=>r.category===id).id;return renderPanel();}if(a==='recipe'){selectedRecipe=id;return renderPanel();}if(a==='craft'){let r=model.craft(id);toast(r.message);save();return renderPanel();}if(a==='lookTab'){if(['Body','Face','Hair','Clothing'].includes(id))appearanceTab=id;return renderPanel();}if(a==='lookDirection'){const n=Number(id);if(Number.isInteger(n)&&n>=0&&n<4)previewDirection=n;return renderPanel();}if(a==='lookGear'){previewGear=!previewGear;return renderPanel();}if(a==='look'){model.setLook(b.dataset.key,Number(id));save();return renderPanel();}if(a==='rest'){model.p.hp=100;save();toast('Health restored. Take care out there.');return close();}if(a==='allowance'){if(model.allowanceClaim()){save();toast('Welcome supplies added.');}return renderPanel();}if(a==='targets'){model.resetTargets();close();toast('Targets reset. Aim with the right stick, or mouse.');return;}if(a==='drill'){model.startDrill(id);close();scene?.cameras.main.centerOn(model.p.x,model.p.y*WORLD.sy);save();return;}if(a==='title'){if(model.drill)model.endDrill('stopped');save();model.events=[];close();welcome=true;show('welcome');hide('hud');$('enter').textContent='Return to the hollow →';return;}if(a==='sound'){settings.sound=!settings.sound;sound('heal');saveSettings();return renderPanel();}if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen&&document.fullscreenEnabled!==false)await document.documentElement.requestFullscreen();else return open('install');}catch{return open('install');}}}
$('sheetBody').onclick=panelAction;$('sheetFooter').onclick=panelAction;
function interact(){if(bridge.paused())return;let s=model.nearest();if(!s)return;if(s.kind==='crate'){model.collect(s.id);save();return;}open(s.kind==='craft'?'craft':s.kind,s);}
$('interact').onclick=interact;$('mapButton').onclick=()=>open('map');$('packButton').onclick=()=>open('equipment');$('loadout').onclick=()=>open('equipment');$('pauseButton').onclick=()=>open('pause');$('installWelcome').onclick=()=>open('install');$('stopDrill').onclick=()=>model.endDrill('stopped');
$('enter').onclick=()=>{if(!ready)return;welcome=false;hide('welcome');show('hud');resetInput();save();sound('heal');};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(panel)close();else if(!welcome)open('pause');return;}if(panel){if(e.key==='Tab'){let nodes=[...$('sheet').querySelectorAll('button:not(:disabled),select,input,a[href]')];if(nodes.length){let i=nodes.indexOf(document.activeElement),next=e.shiftKey?(i-1+nodes.length)%nodes.length:(i+1)%nodes.length;nodes[next].focus();e.preventDefault();}}return;}if(welcome||['INPUT','SELECT'].includes(e.target.tagName))return;let k=e.key.toLowerCase();if([' ','tab','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k===' ')act('dash');if(k==='q')act('heal');if(k==='r')act('reload');if(k==='m')open('map');if(k==='tab')open('equipment');});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
$('game').addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||bridge.paused())return;mouse.down=true;mouse.seen=true;mouse.x=e.clientX;mouse.y=e.clientY;$('game').setPointerCapture(e.pointerId);});window.addEventListener('pointermove',e=>{if(e.pointerType!=='touch'){mouse.x=e.clientX;mouse.y=e.clientY;mouse.seen=true;}});window.addEventListener('pointerup',()=>mouse.down=false);window.addEventListener('pointercancel',()=>mouse.down=false);window.addEventListener('contextmenu',e=>e.preventDefault());
function autoPause(){resetInput();save();if(!welcome&&!panel)open('pause');}
window.addEventListener('blur',autoPause);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)autoPause();});
const bridge={paused:()=>welcome||!!panel||document.hidden,low:()=>settings.low,zoom:()=>{let h=game?.scale.height||innerHeight;return Math.max(.65,Math.min(1.1,h/(touch?540:650)));},pause:autoPause,ready:s=>{scene=s;ready=true;$('enter').disabled=false;$('enter').textContent=stored?'Return to the hollow →':'Enter the hollow →';$('loading').textContent='Village · Workshop · Training yard';},
 input:s=>{let mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+move.x,my=((keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+move.y)/WORLD.sy,angle=model.p.angle,fire=false;if(aim.power>.03){angle=Math.atan2(aim.y/WORLD.sy,aim.x);if(settings.assist){let targets=(model.drill?model.enemies:model.dummies).map(e=>({...e,active:0}));angle=assistedAngle(angle,model.p,targets);}fire=true;}else if(mouse.seen&&!touch){let box=$('game').getBoundingClientRect(),v=s.cameras.main.getWorldPoint(mouse.x-box.left,mouse.y-box.top);angle=Math.atan2(v.y/WORLD.sy-model.p.y, v.x-model.p.x);fire=mouse.down;}else if(Math.hypot(mx,my)>.1)angle=Math.atan2(my,mx);lastInput={mx,my,angle,fire};return lastInput;},
 events:()=>{for(let e of model.events.splice(0)){sound(e.type);if(e.type==='loot')toast(Object.entries(e.loot).map(([k,n])=>'+'+n+' '+MATERIALS[k]).join(' · '));if(e.type==='report'){save();open('report',e);}if(e.type==='drillStart'){hide('hint');toast('Drill started. Keep moving.');}}},
 hud:(now,s)=>{if(now-lastHud<120)return;let dt=(now-lastHud)/1000;lastHud=now;if(!bridge.paused()){hintTimer-=dt;saveAge+=dt;if(saveAge>5){save();saveAge=0;}}if(hintTimer<=0||model.drill)hide('hint');let p=model.p;$('healthLabel').textContent=Math.ceil(p.hp)+' / 100';$('healthFill').style.width=p.hp+'%';$('healthFill').style.background=p.hp<30?'#e4a289':'var(--lime)';$('gearLabel').textContent=ARMORS[model.armor].name;$('weaponLabel').textContent=model.gun.name;$('weaponNote').textContent=model.inYard?'TUNING '+model.upgrades[model.weapon]+' / 3':'HOLSTERED IN VILLAGE';$('ammoLabel').textContent=model.clip+' / '+model.gun.clip;$('reloadLabel').textContent=model.reloadTime>0?'RELOADING':'↻ RELOAD';$('dashLabel').textContent=p.dash>0?p.dash.toFixed(1)+'s':'DASH';$('healLabel').textContent='TONIC · '+model.tonics;$('heal').disabled=model.tonics<=0;$('dash').style.opacity=p.dash>0?'.45':'1';let near=model.nearest();$('interact').classList.toggle('hidden',!near||!!model.drill||welcome);if(near)$('interactName').textContent=near.label;$('drillHud').classList.toggle('hidden',!model.drill);if(model.drill)$('drillStatus').textContent=model.stats.kills+' / '+model.drill.total+' cleared · '+Math.floor(model.drill.elapsed)+'s';let district=model.inYard?'TRAINING YARD':p.x>2400&&p.y<1650?'THE INLET':p.y>1800&&p.x>1750?'MOONLIT SHORE':p.y<950?'THE HIGH TERRACES':'DEADLIGHT HOLLOW';$('district').textContent=district;$('locationNote').textContent=model.inYard?(model.drill?'Keep moving. Make room.':'Targets reset · Ammo supplied'):'A place to call home';}
};
resize();
if(typeof Phaser==='undefined'){$('loading').textContent='The game engine could not load. Refresh to try again.';$('enter').textContent='Reload village';$('enter').disabled=false;$('enter').onclick=()=>location.reload();}else{
 try{game=new Phaser.Game({type:Phaser.AUTO,parent:'game',width:Math.round(window.visualViewport?.width||innerWidth),height:Math.round(window.visualViewport?.height||innerHeight),resolution:Math.min(2,devicePixelRatio||1),backgroundColor:'#171e30',banner:false,audio:{noAudio:true},render:{antialias:false,pixelArt:true,roundPixels:true,powerPreference:'low-power'},fps:{target:60},scene:makeScene(model,bridge)});}catch(e){console.error(e);$('loading').textContent='Unable to start the village. Try reloading this page.';}
}
window.addEventListener('error',e=>{console.error(e.error);if(ready){autoPause();toast('Paused after an error. Your last save is safe.');}else $('loading').textContent='The village could not finish loading. Refresh to try again.';});
